create extension if not exists pgcrypto;
create type public.user_role as enum ('agent','client','admin');create type public.submission_status as enum ('draft','submitted','flagged','approved','rejected');create type public.payout_status as enum ('requested','processing','paid','failed');
create table public.profiles(id uuid primary key references auth.users on delete cascade,role user_role not null default 'agent',first_name text,country_code char(2),gdpr_photo boolean default false,gdpr_location boolean default false,terms_accepted_at timestamptz,approved_jobs int not null default 0,banned_at timestamptz,created_at timestamptz default now());
create table public.stores(id uuid primary key default gen_random_uuid(),client_id uuid references public.profiles,address text not null,chain text,lat double precision not null,lng double precision not null);
create table public.jobs(id uuid primary key default gen_random_uuid(),client_id uuid references public.profiles,store_id uuid references public.stores,title text not null,job_type text not null,reward_cents int check(reward_cents>0),refund_cents int default 0,estimated_minutes int not null,starts_at timestamptz,ends_at timestamptz,steps jsonb not null default '[]',published boolean default false,created_at timestamptz default now());
create table public.reservations(id uuid primary key default gen_random_uuid(),job_id uuid references public.jobs on delete cascade,agent_id uuid references public.profiles on delete cascade,reserved_at timestamptz default now(),expires_at timestamptz not null,completed_at timestamptz,unique(job_id));create unique index one_active_job on public.reservations(agent_id) where completed_at is null;
create table public.submissions(id uuid primary key default gen_random_uuid(),job_id uuid references public.jobs,agent_id uuid references public.profiles,status submission_status default 'draft',answers jsonb default '{}',captured_lat double precision,captured_lng double precision,captured_at timestamptz,gps_distance_m int,gps_verified boolean default false,rejection_reason text,reviewed_by uuid references public.profiles,reviewed_at timestamptz,created_at timestamptz default now());
create table public.wallet_entries(id uuid primary key default gen_random_uuid(),agent_id uuid references public.profiles,submission_id uuid references public.submissions,amount_cents int not null,status text not null,created_at timestamptz default now());create table public.payouts(id uuid primary key default gen_random_uuid(),agent_id uuid references public.profiles,amount_cents int check(amount_cents>=1000),iban_last4 char(4),iban_encrypted text,status payout_status default 'requested',created_at timestamptz default now());
alter table public.profiles enable row level security;alter table public.stores enable row level security;alter table public.jobs enable row level security;alter table public.reservations enable row level security;alter table public.submissions enable row level security;alter table public.wallet_entries enable row level security;alter table public.payouts enable row level security;
create policy "own profile" on public.profiles for select using(auth.uid()=id);create policy "published jobs" on public.jobs for select using(published=true or client_id=auth.uid());create policy "stores for signed in" on public.stores for select to authenticated using(true);create policy "own reservations" on public.reservations for all using(agent_id=auth.uid()) with check(agent_id=auth.uid());create policy "own or client submissions" on public.submissions for select using(agent_id=auth.uid() or exists(select 1 from jobs where jobs.id=job_id and jobs.client_id=auth.uid()));create policy "agent creates submission" on public.submissions for insert with check(agent_id=auth.uid());create policy "own wallet" on public.wallet_entries for select using(agent_id=auth.uid());create policy "own payouts" on public.payouts for all using(agent_id=auth.uid()) with check(agent_id=auth.uid());
create or replace function public.reserve_job(p_job uuid) returns public.reservations language plpgsql security definer set search_path=public as $$declare r reservations;begin delete from reservations where completed_at is null and expires_at<now();if exists(select 1 from reservations where agent_id=auth.uid() and completed_at is null) then raise exception 'ONE_ACTIVE_JOB';end if;insert into reservations(job_id,agent_id,expires_at) values(p_job,auth.uid(),now()+interval '60 minutes') returning * into r;return r;end$$;
